
import type { MoneyValueInput } from './MoneyValueInput.js';

export type CheckoutTipConfigInput = { /** The preselected fixed tip, with a positive amount in the same currency as smart_tip_money_options. Its amount and currency must match one of the effective smart_tip_money_options: the ones sent here, or else the ones inherited from tipping settings. An inherited preselection that isn't one of the effective options is dropped. */ "default_smart_tip_money"?: MoneyValueInput; /** The preselected tip percent, from 1 through 100 with at most four decimal places. Must match one of the effective tip_percent_options: the ones sent here, or else the ones inherited from tipping settings. An inherited preselection that isn't one of the effective options is dropped, and checkout preselects no tip. minimum: 1. maximum: 100. multipleOf: 0.0001. */ "default_tip_percent"?: number; "enabled"?: boolean; "is_custom_tip_enabled"?: boolean; "is_smart_tips_enabled"?: boolean; /** Three fixed tips to offer, each with a positive amount. On a checkout session they must use the session's currency. On a payment link they must share one currency, and a checkout opened from the link offers only those in its currency. */ "smart_tip_money_options"?: Array<MoneyValueInput>; /** Three tip percents to offer, each from 1 through 100 with at most four decimal places. */ "tip_percent_options"?: Array<number>; };
